CREATE SCHEMA IF NOT EXISTS sanket;
CREATE TABLE IF NOT EXISTS sanket.settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), data jsonb NOT NULL DEFAULT '{"businessName":"Sanket Distribution","timezone":"Asia/Kolkata","phone":"","address":"","trackingInterval":60,"staleMinutes":10,"retentionDays":30}');
INSERT INTO sanket.settings(id) VALUES(true) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS sanket.locations (id uuid PRIMARY KEY, name text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS sanket.warehouses (id uuid PRIMARY KEY, name text NOT NULL UNIQUE, location_id uuid NOT NULL REFERENCES sanket.locations(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS sanket.vehicles (id uuid PRIMARY KEY, name text NOT NULL UNIQUE, registration text NOT NULL DEFAULT '', warehouse_id uuid NOT NULL REFERENCES sanket.warehouses(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS sanket.assignments (id uuid PRIMARY KEY, vehicle_id uuid NOT NULL REFERENCES sanket.vehicles(id), salesman_id uuid NOT NULL REFERENCES sanket.users(id), starts_at timestamptz NOT NULL DEFAULT now(), ends_at timestamptz, actor_id uuid NOT NULL REFERENCES sanket.users(id), reason text NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS assignment_active_vehicle ON sanket.assignments(vehicle_id) WHERE ends_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS assignment_active_salesman ON sanket.assignments(salesman_id) WHERE ends_at IS NULL;
CREATE TABLE IF NOT EXISTS sanket.products (id uuid PRIMARY KEY, sku text NOT NULL DEFAULT '', name text NOT NULL, category text NOT NULL, active boolean NOT NULL DEFAULT true, min_stock bigint NOT NULL DEFAULT 0 CHECK(min_stock>=0), price numeric(18,2), price_unit text, currency text NOT NULL DEFAULT 'INR', raw_import jsonb, canonical_base_unit text, active_packaging_id uuid, created_at timestamptz NOT NULL DEFAULT now(), CHECK(price IS NULL OR price>=0));
CREATE UNIQUE INDEX IF NOT EXISTS product_sku ON sanket.products(lower(sku)) WHERE sku<>'';
CREATE UNIQUE INDEX IF NOT EXISTS product_name_category ON sanket.products(lower(name),lower(category));
CREATE TABLE IF NOT EXISTS sanket.packaging (id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES sanket.products(id), version integer NOT NULL CHECK(version>0), base_unit text NOT NULL, levels jsonb NOT NULL, reason text NOT NULL, actor_id uuid NOT NULL REFERENCES sanket.users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(product_id,version));
DO $$ BEGIN ALTER TABLE sanket.products ADD CONSTRAINT product_packaging_fk FOREIGN KEY(active_packaging_id) REFERENCES sanket.packaging(id); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS sanket.stock_balances (location_type text NOT NULL CHECK(location_type IN ('warehouse','vehicle')), location_id uuid NOT NULL, product_id uuid NOT NULL REFERENCES sanket.products(id), quantity bigint NOT NULL DEFAULT 0 CHECK(quantity>=0 AND quantity<=9007199254740991), PRIMARY KEY(location_type,location_id,product_id));
CREATE TABLE IF NOT EXISTS sanket.stock_documents (id uuid PRIMARY KEY, reference text NOT NULL UNIQUE, kind text NOT NULL, warehouse_id uuid REFERENCES sanket.warehouses(id), vehicle_id uuid REFERENCES sanket.vehicles(id), actor_id uuid NOT NULL REFERENCES sanket.users(id), actor_name text NOT NULL, salesman_id uuid REFERENCES sanket.users(id), salesman_name text, assignment_id uuid REFERENCES sanket.assignments(id), day date NOT NULL, status text NOT NULL DEFAULT 'POSTED', lines jsonb NOT NULL, notes text NOT NULL DEFAULT '', replaces_id uuid UNIQUE REFERENCES sanket.stock_documents(id), replaced_by_id uuid REFERENCES sanket.stock_documents(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS documents_vehicle_day ON sanket.stock_documents(vehicle_id,day,created_at);
CREATE INDEX IF NOT EXISTS documents_salesman_day ON sanket.stock_documents(salesman_id,day);
CREATE TABLE IF NOT EXISTS sanket.stock_movements (id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES sanket.products(id), location_type text NOT NULL CHECK(location_type IN ('warehouse','vehicle')), location_id uuid NOT NULL, quantity bigint NOT NULL CHECK(quantity<>0), kind text NOT NULL, document_id uuid NOT NULL REFERENCES sanket.stock_documents(id), reference text NOT NULL, actor_id uuid NOT NULL REFERENCES sanket.users(id), actor_name text NOT NULL, day date NOT NULL, note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS movements_scope_day_product ON sanket.stock_movements(location_type,location_id,day,product_id);
CREATE INDEX IF NOT EXISTS movements_product_day ON sanket.stock_movements(product_id,day);
CREATE TABLE IF NOT EXISTS sanket.invoices (id uuid PRIMARY KEY, revision integer NOT NULL DEFAULT 1 CHECK(revision>0), file_id text NOT NULL, file_name text NOT NULL, mime text NOT NULL, hash text NOT NULL UNIQUE, supplier text NOT NULL DEFAULT '', invoice_number text NOT NULL DEFAULT '', invoice_date text NOT NULL DEFAULT '', warehouse_id uuid REFERENCES sanket.warehouses(id), status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','READY_FOR_APPROVAL','APPROVED_POSTED','REJECTED')), extraction_status text NOT NULL DEFAULT 'QUEUED', extraction_error text NOT NULL DEFAULT '', extracted_text text NOT NULL DEFAULT '', suggestions jsonb, extraction_meta jsonb, lines jsonb NOT NULL DEFAULT '[]', created_by uuid NOT NULL REFERENCES sanket.users(id), created_at timestamptz NOT NULL DEFAULT now(), approved_at timestamptz, approved_by uuid REFERENCES sanket.users(id), receipt_id uuid UNIQUE REFERENCES sanket.stock_documents(id), receipt_reference text, decision_reason text NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS invoice_supplier_number ON sanket.invoices(lower(trim(supplier)),lower(trim(invoice_number))) WHERE supplier<>'' AND invoice_number<>'';
CREATE TABLE IF NOT EXISTS sanket.invoice_revisions (invoice_id uuid NOT NULL REFERENCES sanket.invoices(id), revision integer NOT NULL, snapshot jsonb NOT NULL, actor_id uuid NOT NULL REFERENCES sanket.users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(invoice_id,revision));
CREATE INDEX IF NOT EXISTS invoices_status ON sanket.invoices(status,created_at);
CREATE TABLE IF NOT EXISTS sanket.daily_reports (id uuid PRIMARY KEY, vehicle_id uuid NOT NULL REFERENCES sanket.vehicles(id), day date NOT NULL, revision integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'DRAFT', sealed boolean NOT NULL DEFAULT false, UNIQUE(vehicle_id,day));
CREATE TABLE IF NOT EXISTS sanket.report_revisions (id uuid PRIMARY KEY, report_id uuid NOT NULL REFERENCES sanket.daily_reports(id), revision integer NOT NULL, snapshot jsonb NOT NULL, source_hash text NOT NULL, submitter_id uuid NOT NULL REFERENCES sanket.users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(report_id,revision));
CREATE TABLE IF NOT EXISTS sanket.report_decisions (id uuid PRIMARY KEY, report_id uuid NOT NULL REFERENCES sanket.daily_reports(id), revision integer NOT NULL, decision text NOT NULL CHECK(decision IN ('APPROVED','REJECTED','REOPENED')), actor_id uuid NOT NULL REFERENCES sanket.users(id), actor_name text NOT NULL, reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(report_id,revision) REFERENCES sanket.report_revisions(report_id,revision));
CREATE INDEX IF NOT EXISTS report_status_day ON sanket.daily_reports(status,day);
CREATE TABLE IF NOT EXISTS sanket.requests (actor_id uuid NOT NULL REFERENCES sanket.users(id), action text NOT NULL, request_id text NOT NULL, payload_hash text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,action,request_id));
CREATE TABLE IF NOT EXISTS sanket.audit (id uuid PRIMARY KEY, action text NOT NULL, entity_id text NOT NULL DEFAULT '', actor_id uuid NOT NULL REFERENCES sanket.users(id), actor_name text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sanket.location_samples (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES sanket.users(id), user_name text NOT NULL, vehicle_id uuid NOT NULL REFERENCES sanket.vehicles(id), assignment_id uuid NOT NULL REFERENCES sanket.assignments(id), latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), accuracy double precision NOT NULL CHECK(accuracy>=0), captured_at timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS samples_vehicle_time ON sanket.location_samples(vehicle_id,received_at DESC);
CREATE OR REPLACE FUNCTION sanket.immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable historical record'; END $$;
DO $$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['packaging','stock_movements','invoice_revisions','report_revisions','report_decisions','audit'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS immutable_history ON sanket.%I',tab); EXECUTE format('CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON sanket.%I FOR EACH ROW EXECUTE FUNCTION sanket.immutable_record()',tab); END LOOP; END $$;
